import type { ExpressionSpecification, Map as MapLibreMap } from "maplibre-gl";

// Az ikonokat kétszeres felbontásban rajzoljuk, hogy retina kijelzőn is élesek legyenek.
const ICON_PIXEL_RATIO = 2;
const VEHICLE_ICON_SIZE = 30;
const HEADING_ICON_SIZE = 52;

export const HEADING_ICON_ID = "vehicle-heading";

export type IconScheme = "light" | "dark";

const withScheme = (id: string, scheme: IconScheme) =>
  scheme === "dark" ? id + DARK_SUFFIX : id;

export const headingIconId = (scheme: IconScheme) =>
  withScheme(HEADING_ICON_ID, scheme);

const DARK_SUFFIX = "-dark";

// A jármű körvonala és az irányt mutató háromszög azonos színű.
// Sötét módban sötétszürke (#565656).
const OUTLINE_COLOR = { light: "#003A7E", dark: "#565656" };

const DELAY_ICON_COLORS: Record<string, string> = {
  "vehicle-delay-0": "#00FF00",
  "vehicle-delay-5": "#FFFF00",
  "vehicle-delay-15": "#FFA500",
  "vehicle-delay-60": "#FA3031",
};

// A késés másodpercben érkezik: 5, 15 és 60 percnél vált színt az ikon.
export const vehicleIconExpression = (
  scheme: IconScheme
): ExpressionSpecification => [
  "step",
  ["coalesce", ["get", "delay"], 0],
  withScheme("vehicle-delay-0", scheme),
  5 * 60,
  withScheme("vehicle-delay-5", scheme),
  15 * 60,
  withScheme("vehicle-delay-15", scheme),
  60 * 60,
  withScheme("vehicle-delay-60", scheme),
];

